function backtrack(partial):
    if partial is complete (length == n):
        record a COPY of partial
        return
    for each candidate not yet used:
        choose(candidate)     // add to partial, mark used
        backtrack(partial)    // explore
        unchoose(candidate)   // remove from partial, mark unused

void backtrack(vector<int>& nums, vector<int>& current, vector<bool>& used, vector<vector<int>>& result) {
    if (current.size() == nums.size()) {
        result.push_back(current);
        return;
    }
    for (int i = 0; i < nums.size(); i++) {
        if (used[i]) continue;
        // choose
        used[i] = true;
        current.push_back(nums[i]);
        // explore
        backtrack(nums, current, used, result);
        // unchoose
        current.pop_back();
        used[i] = false;
    }
}

vector<vector<int>> permute(vector<int>& nums) {
    vector<vector<int>> result;
    vector<int> current;
    vector<bool> used(nums.size(), false);
    backtrack(nums, current, used, result);
    return result;
}

void backtrack(vector<int>& nums, int index, vector<vector<int>>& result) {
    if (index == nums.size()) {
        result.push_back(nums);
        return;
    }
    for (int i = index; i < nums.size(); i++) {
        swap(nums[index], nums[i]);   // choose
        backtrack(nums, index + 1, result); // explore
        swap(nums[index], nums[i]);   // unchoose (undo the swap)
    }
}

vector<vector<int>> permute(vector<int>& nums) {
    vector<vector<int>> result;
    backtrack(nums, 0, result);
    return result;
}

void backtrack(vector<int>& nums, vector<int>& current, vector<bool>& used, vector<vector<int>>& result) {
    if (current.size() == nums.size()) {
        result.push_back(current);
        return;
    }
    for (int i = 0; i < nums.size(); i++) {
        if (used[i]) continue;
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue; // skip duplicate
        used[i] = true;
        current.push_back(nums[i]);
        backtrack(nums, current, used, result);
        current.pop_back();
        used[i] = false;
    }
}

vector<vector<int>> permuteUnique(vector<int>& nums) {
    sort(nums.begin(), nums.end()); // sorting first is required for the skip condition to work
    vector<vector<int>> result;
    vector<int> current;
    vector<bool> used(nums.size(), false);
    backtrack(nums, current, used, result);
    return result;
}

void heapPermute(vector<int>& nums, int k, vector<vector<int>>& result) {
    if (k == 1) {
        result.push_back(nums);
        return;
    }
    for (int i = 0; i < k; i++) {
        heapPermute(nums, k - 1, result);
        if (k % 2 == 0) swap(nums[i], nums[k - 1]);
        else swap(nums[0], nums[k - 1]);
    }
}
